// Formats the IR from collect.js as C#. No TypeSpec APIs in here — only strings.

import { str, xmlText } from "./names.js";

const HEADER = (namespace, usings) =>
  [
    "// <auto-generated>",
    "//   Generated by @olivervea/typespec-csharp from the TypeSpec contract. Do not edit:",
    "//   change the spec (or the emitter) and rebuild.",
    "// </auto-generated>",
    "#nullable enable",
    ...usings.map((u) => `using ${u};`),
    "",
    `namespace ${namespace};`,
    "",
  ].join("\n");

const summary = (doc, indent = "") => (doc ? `${indent}/// <summary>${xmlText(doc)}</summary>\n` : "");

const MAP_METHODS = { get: "MapGet", post: "MapPost", put: "MapPut", delete: "MapDelete", patch: "MapPatch" };
const FROM = { path: "FromRoute", query: "FromQuery", header: "FromHeader" };

/** Records, enums, discriminated unions and request validators. */
export function renderModels(ir, namespace) {
  const out = [
    HEADER(namespace, [
      "System",
      "System.Collections.Generic",
      "System.Text.Json.Serialization",
      "Olve.Results",
      "Olve.TypeSpec",
      "Olve.Validation",
    ]),
  ];

  for (const e of ir.enums.values()) {
    let s = summary(e.doc);
    if (!e.numeric) s += `[JsonConverter(typeof(JsonStringEnumConverter<${e.name}>))]\n`;
    s += `public enum ${e.name}\n{\n`;
    for (const m of e.members) {
      s += summary(m.doc, "    ");
      s += e.numeric
        ? `    ${m.name} = ${m.value},\n`
        : `    [JsonStringEnumMemberName(${str(m.value)})]\n    ${m.name},\n`;
    }
    out.push(`${s}}\n`);
  }

  for (const u of ir.unions.values()) {
    let s = summary(u.doc);
    s += `[JsonPolymorphic(TypeDiscriminatorPropertyName = ${str(u.discriminator)})]\n`;
    for (const v of u.variants) s += `[JsonDerivedType(typeof(${v.name}), ${str(v.key)})]\n`;
    if (!u.events) {
      s += `public abstract record ${u.name};\n`;
    } else {
      // An SSE event union: each event knows its event name (its `type`, written by the polymorphism).
      s += `public abstract record ${u.name} : IServerSentEvent\n{\n`;
      s += "    /// <summary>Every event name (<c>type</c>) of the stream, in contract order.</summary>\n";
      s += `    public static IReadOnlyList<string> EventTypes { get; } = [${u.variants.map((v) => str(v.key)).join(", ")}];\n\n`;
      s += "    /// <inheritdoc />\n    [JsonIgnore]\n    public abstract string EventType { get; }\n}\n";
    }
    out.push(s);
  }

  for (const m of ir.models.values()) {
    let s = m.writableOf
      ? `/// <summary>Request shape of <see cref="${m.writableOf}"/> (only the properties a client may send).</summary>\n`
      : summary(m.doc);
    s += `public sealed record ${m.name}${m.union ? ` : ${m.union.name}` : ""}\n{\n`;
    const members = m.props.map((p) => renderProperty(p));
    if (m.union?.events)
      members.unshift(
        `    /// <inheritdoc />\n    [JsonIgnore]\n    public override string EventType => ${str(m.union.key)};\n`,
      );
    s += members.join("\n");
    out.push(`${s}}\n`);
  }

  for (const v of ir.validators) {
    let s = `/// <summary>Validates <see cref="${v.model}"/> against the spec's constraints.</summary>\n`;
    s += `public sealed class ${v.name} : IValidator<${v.model}>\n{\n`;
    s += `    public Result Validate(${v.model} value) => Result.Concat(\n    [\n`;
    for (const r of v.rules) s += `        ${r.test} ? new ResultProblem(${str(r.message)}) : Result.Success(),\n`;
    s += "    ]);\n}\n";
    out.push(s);
  }

  return out.join("\n");
}

function renderProperty(p) {
  const attrs = [`JsonPropertyName(${str(p.wire)})`];
  // Optional, non-nullable: omit rather than write `null`. Nullable properties always write.
  if (p.optional && !p.nullable) attrs.push("JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)");
  return (
    summary(p.doc, "    ") +
    `    [${attrs.join(", ")}]\n` +
    `    public ${p.optional ? "" : "required "}${p.type} ${p.name} { get; init; }\n`
  );
}

/** Per-operation request records + handler interfaces, the operation table, Add/Use/Map. */
export function renderApi(ir, namespace, prefix) {
  const out = [
    HEADER(namespace, [
      "System",
      "System.Collections.Generic",
      "System.Threading",
      "Microsoft.AspNetCore.Builder",
      "Microsoft.AspNetCore.Http",
      "Microsoft.AspNetCore.Mvc",
      "Microsoft.AspNetCore.Routing",
      "Microsoft.Extensions.DependencyInjection",
      "Olve.TypeSpec",
    ]),
  ];

  for (const o of ir.operations) {
    const fields = [...o.params.map((p) => `${p.type} ${p.name}`), ...(o.body ? [`${o.body.type} Body`] : [])];
    let s = `/// <summary>Input of <c>${o.operationId}</c> (${o.verb.toUpperCase()} ${o.path}).</summary>\n`;
    s += `public sealed record ${o.name}Request${fields.length ? `(${fields.join(", ")})` : ""};\n\n`;
    s += renderResponseUnion(o);
    s += summary(o.doc);
    s += `public interface I${o.name}Handler : IOperationHandler<${o.name}Request, ${o.name}Response>;\n`;
    out.push(s);
  }

  let table = "/// <summary>Every operation's id, success statuses and declared error statuses.</summary>\n";
  table += `public static class ${prefix}Operations\n{\n`;
  for (const o of ir.operations) {
    table += `    public static readonly ApiOperation ${o.name} = new(${str(o.operationId)}, [${o.successes.map((r) => r.status).join(", ")}], [${o.errors.map((e) => e.status).join(", ")}]);\n`;
  }
  out.push(`${table}}\n`);

  let endpoints =
    "/// <summary>The route builder of each mapped operation, for app-side conventions (auth, rate limits, …).</summary>\n";
  endpoints += `public sealed class ${prefix}Endpoints\n{\n`;
  endpoints += ir.operations.map((o) => `    public required RouteHandlerBuilder ${o.name} { get; init; }\n`).join("");
  out.push(`${endpoints}}\n`);

  let api = `public static class ${prefix}Api\n{\n`;
  api +=
    "    /// <summary>Every operation's handler interface; each must have a registered implementation.</summary>\n";
  api += `    public static IReadOnlyList<Type> HandlerTypes { get; } =\n    [\n${ir.operations.map((o) => `        typeof(I${o.name}Handler),\n`).join("")}    ];\n\n`;
  api +=
    '    /// <summary>Registers the generated JSON context and the runtime\'s request handling (the app registers its <see cref="IApiErrorWriter"/> and handlers).</summary>\n';
  api += `    public static IServiceCollection Add${prefix}Api(this IServiceCollection services) => services.AddTypeSpecApi(${prefix}JsonContext.Default);\n\n`;
  api +=
    "    /// <summary>Checks every handler is registered, adds the runtime's middleware and maps every contract operation.</summary>\n";
  api += `    public static ${prefix}Endpoints Use${prefix}Api(this WebApplication app) => app.UseTypeSpecApi(HandlerTypes).Map${prefix}Api();\n\n`;
  api += "    /// <summary>Maps every contract operation onto its handler interface.</summary>\n";
  api += `    public static ${prefix}Endpoints Map${prefix}Api(this IEndpointRouteBuilder app) => new()\n    {\n`;
  api += ir.operations.map((o) => renderEndpoint(o, ir, prefix)).join("");
  api += "    };\n}\n";
  out.push(api);

  const parsed = [...new Set(ir.operations.flatMap((o) => o.params.map((p) => stringEnumOf(p, ir)).filter(Boolean)))];
  if (parsed.length)
    out.push(
      renderEnumParsers(
        parsed.map((name) => ir.enums.get(name)),
        prefix,
      ),
    );

  return out.join("\n");
}

/** The string enum a parameter binds to, if any (minimal APIs would parse it by C# member name). */
function stringEnumOf(p, ir) {
  const e = ir.enums.get(p.type.replace(/\?$/, ""));
  return e && !e.numeric ? e.name : undefined;
}

/** Parses string-enum parameters by their wire values; anything else is a binding failure. */
function renderEnumParsers(enums, prefix) {
  let s =
    "/// <summary>Parses string-enum parameters by their wire values (minimal APIs only know member names).</summary>\n";
  s += `internal static class ${prefix}Parameters\n{\n`;
  s += enums
    .map((e) => {
      let m = `    public static ${e.name} Parse${e.name}(string value, string parameter) => value switch\n    {\n`;
      for (const member of e.members) m += `        ${str(member.value)} => ${e.name}.${member.name},\n`;
      m +=
        '        _ => throw new BadHttpRequestException($"Failed to bind parameter \\"{parameter}\\" from \\"{value}\\"."),\n';
      return `${m}    };\n`;
    })
    .join("\n");
  return `${s}}\n`;
}

function renderEndpoint(o, ir, prefix) {
  const route = MAP_METHODS[o.verb]
    ? `app.${MAP_METHODS[o.verb]}(${str(o.route)}, `
    : `app.MapMethods(${str(o.route)}, [${str(o.verb.toUpperCase())}], `;
  const lambdaParams = [
    `[FromServices] I${o.name}Handler handler`,
    ...o.params.map((p) => {
      // String enums bind as strings and are parsed by wire value (see renderEnumParsers);
      // explode:false lists bind as one string and are split (QueryParameters.List).
      const type = stringEnumOf(p, ir) || p.list ? (p.type.endsWith("?") ? "string?" : "string") : p.type;
      return `[${FROM[p.kind]}(Name = ${str(p.wire)})] ${type} ${p.local}`;
    }),
    // A Stream parameter binds the raw request body, whatever its content type.
    ...(o.body ? [o.body.raw ? `${o.body.type} body` : `[FromBody] ${o.body.type} body`] : []),
    "CancellationToken ct",
  ];
  const arg = (p) => {
    if (p.list) return `QueryParameters.List(${p.local})`;
    if (p.catchAll) return `PathParameters.CatchAll(${p.local})`;
    const e = stringEnumOf(p, ir);
    if (!e) return p.local;
    const parse = `${prefix}Parameters.Parse${e}(${p.local}, ${str(p.wire)})`;
    return p.type.endsWith("?") ? `${p.local} is null ? null : ${parse}` : parse;
  };
  const args = [...o.params.map(arg), ...(o.body ? ["body"] : [])].join(", ");
  const i = "        ";
  let s = `${i}${o.name} = ${route}async (\n`;
  s += lambdaParams.map((p) => `${i}        ${p}`).join(",\n");
  s += ") =>\n";
  s += `${i}        (await handler.HandleAsync(new ${o.name}Request(${args}), ct)).ToHttpResult())\n`;
  s += `${i}    .WithName(${str(o.operationId)})\n`;
  s += `${i}    .WithMetadata(${prefix}Operations.${o.name})`;
  if (o.body?.validator)
    s += `\n${i}    .WithRequestValidation<${o.body.type}, ${o.body.validator}>(${prefix}Operations.${o.name})`;
  for (const r of [...o.successes, ...o.errors]) s += `\n${i}    ${produces(r)}`;
  return `${s},\n`;
}

function produces(r) {
  switch (r.kind) {
    case "sse":
      return `.Produces<${r.type}>(${r.status}, "text/event-stream")`;
    case "json":
      return `.Produces<${r.type}>(${r.status})`;
    case "text":
      return `.Produces<string>(${r.status}, ${str(r.contentType ?? "text/plain")})`;
    case "binary":
      return `.Produces(${r.status}, null, ${str(r.contentType ?? "application/octet-stream")})`;
    default:
      return `.Produces(${r.status})`;
  }
}

// Variant names of a response union, by status.
const STATUS_NAMES = {
  200: "Ok",
  201: "Created",
  202: "Accepted",
  204: "NoContent",
  400: "BadRequest",
  401: "Unauthorized",
  403: "Forbidden",
  404: "NotFound",
  409: "Conflict",
  410: "Gone",
  413: "PayloadTooLarge",
  422: "UnprocessableEntity",
  429: "TooManyRequests",
  500: "InternalServerError",
  503: "ServiceUnavailable",
};
const variantName = (status) => STATUS_NAMES[status] ?? `Status${status}`;

/** Interfaces can't take part in user-defined conversions (CS0552). */
const isInterface = (type) =>
  /^(IReadOnlyList|IReadOnlyDictionary|IAsyncEnumerable)</.test(type) || type === "System.Text.Json.JsonElement";

/**
 * Every response an operation declares, as a closed union: one nested variant per status that
 * writes itself (its body as JSON, an SSE stream, or the status alone). Handlers return a
 * variant, so an undeclared status can't compile. A success body type no other variant carries
 * converts implicitly (`return widget;` for `Ok`); errors are always named
 * (`new NotFound(error)`).
 */
function renderResponseUnion(o) {
  const union = `${o.name}Response`;
  let s = `/// <summary>The responses <c>${o.operationId}</c> declares; its handler returns one.</summary>\n`;
  s += `public abstract record ${union} : IOperationResponse\n{\n`;
  s += `    private ${union}()\n    {\n    }\n\n`;
  s += "    /// <inheritdoc />\n    public abstract int Status { get; }\n\n";
  s += "    /// <inheritdoc />\n    public abstract IResult ToHttpResult();\n";
  const responses = [...o.successes, ...o.errors];
  for (const r of responses) {
    const name = variantName(r.status);
    s += `\n    /// <summary>${r.status}.</summary>\n`;
    s += `    public sealed record ${name}(${variantFields(r).join(", ")}) : ${union}\n    {\n`;
    s += `        /// <inheritdoc />\n        public override int Status => ${r.status};\n\n`;
    s += `        /// <inheritdoc />\n        public override IResult ToHttpResult() => ${variantWrite(r)};\n    }\n`;
  }
  const counts = new Map();
  for (const r of responses) if (r.kind === "json") counts.set(r.type, (counts.get(r.type) ?? 0) + 1);
  for (const r of o.successes) {
    if (r.kind !== "json" || r.headers.length || counts.get(r.type) !== 1 || isInterface(r.type)) continue;
    s += `\n    public static implicit operator ${union}(${r.type} body) => new ${variantName(r.status)}(body);\n`;
  }
  return `${s}}\n\n`;
}

/** A variant's members: its body, an open content type, then its headers (optional ones last, defaulting to null). */
function variantFields(r) {
  const body = {
    sse: `IAsyncEnumerable<ServerSentEvent<${r.type}>> Events`,
    json: `${r.type} Body`,
    text: "string Body",
    binary: "System.IO.Stream Body",
  }[r.kind];
  const open = (r.kind === "text" || r.kind === "binary") && !r.contentType ? ["string ContentType"] : [];
  const headers = r.headers.filter((h) => !h.constant);
  return [
    ...(body ? [body] : []),
    ...open,
    ...headers.filter((h) => !h.optional).map((h) => `${h.type} ${h.name}`),
    ...headers.filter((h) => h.optional).map((h) => `${h.type}? ${h.name} = null`),
  ];
}

function variantWrite(r) {
  const contentType = r.contentType ? str(r.contentType) : "ContentType";
  const body = {
    sse: `new ServerSentEventsResult<${r.type}>(Events)`,
    json: `new JsonResponse<${r.type}>(Body, ${r.status})`,
    text: `new TextResponse(Body, ${contentType}, ${r.status})`,
    binary: `new StreamResponse(Body, ${contentType}, ${r.status})`,
    none: `TypedResults.StatusCode(${r.status})`,
  }[r.kind];
  if (!r.headers.length) return body;
  const value = (h) => {
    if (h.constant !== undefined) return str(h.constant);
    if (h.type === "string") return h.name;
    return `${h.name}${h.optional ? "?" : ""}.ToString(System.Globalization.CultureInfo.InvariantCulture)`;
  };
  const headers = r.headers.map((h) => `new(${str(h.wire)}, ${value(h)})`).join(", ");
  return `new ResponseHeaders(${body}, [${headers}])`;
}

/** The System.Text.Json source-generation context for every DTO. */
export function renderJsonContext(ir, namespace, prefix) {
  let s = HEADER(namespace, [
    "System.Collections.Generic",
    "System.Text.Json",
    "System.Text.Json.Serialization",
    "Olve.Results",
  ]);
  s += "\n[JsonSourceGenerationOptions(JsonSerializerDefaults.Web, AllowOutOfOrderMetadataProperties = true)]\n";
  for (const t of ir.jsonTypes) s += `[JsonSerializable(typeof(${t}))]\n`;
  s += `public partial class ${prefix}JsonContext : JsonSerializerContext;\n`;
  return s;
}
